async function getLoginState() {
	let auth;
	try {
		auth = await readStoredAuth();
	} catch (error) {
		noteStorageFailure(error);
		return {
			isLoggedIn: false,
			username: null,
			storageUnavailable: true
		};
	}
	noteStorageRecovered();
	if (!auth) return {
		isLoggedIn: false,
		username: null
	};
	const username = auth?.profile?.preferred_username || auth?.profile?.email;
	if (!auth.refresh_token || !username) return {
		isLoggedIn: false,
		username: null
	};
	try {
		await menuLoggedIn({ username });
	} catch (error) {
		console.error("Could not update the Thunderbird Pro menu:", error);
	}
	return {
		isLoggedIn: true,
		username
	};
